<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#0f172a;font-size:12px}.header{text-align:center;border-bottom:2px solid #d97706;padding-bottom:18px}.title{font-size:24px;font-weight:bold}.grid{width:100%;margin-top:24px;border-collapse:collapse}.grid td{padding:8px;border-bottom:1px solid #ddd}.amount{font-size:28px;font-weight:bold;text-align:center;margin:28px}.footer{margin-top:35px;font-size:10px;color:#475569;word-break:break-all}</style></head><body><div class="header"><strong>MJIC IMMOBILIER SARL</strong><div class="title">CITÉ ÉTOILE DU MONDE</div><p>Reçu de paiement {{ $receipt->receipt_number }}</p></div><div class="amount">{{ $receipt->amount }} USD</div><table class="grid"><tr><td>Date</td><td>{{ $receipt->issued_at->format('d/m/Y H:i') }}</td></tr><tr><td>Client</td><td>{{ $receipt->customer->first_name }} {{ $receipt->customer->last_name }} ({{ $receipt->customer->customer_number }})</td></tr><tr><td>Parcelle</td><td>{{ $receipt->subscription->plot->reference }} · {{ $receipt->subscription->plot->avenue->neighborhood->name }}</td></tr><tr><td>Formule</td><td>{{ $receipt->subscription->paymentPlan->name }}</td></tr><tr><td>Mode</td><td>{{ $receipt->payment->payment_method }}</td></tr><tr><td>Cumul payé</td><td>{{ $receipt->subscription->amount_paid }} USD</td></tr><tr><td>Solde restant</td><td>{{ $receipt->subscription->balance }} USD</td></tr><tr><td>Agent</td><td>{{ $receipt->issuedBy?->first_name }} {{ $receipt->issuedBy?->last_name }}</td></tr></table><div class="footer"><p>Code de vérification : {{ $receipt->verification_code }}</p><p>Vérifier ce reçu : {{ $verificationUrl }}</p><p>Statut : {{ $receipt->status }}</p></div></body></html>
